{
  "summary": "In v0.5.0, FakeClock was converted from an interface to a struct, requiring direct instantiation via constructors like NewFakeClock or NewFakeClockAt. Additionally, several methods were added to FakeClock (e.g., After, AfterFunc, NewTicker, NewTimer, Now, Since, Sleep, Until, WithDeadline, WithTimeout, BlockUntilContext), while BlockUntil was deprecated.",
  "breaking": [
    {
      "symbol": "FakeClock",
      "change": "converted from an interface to a struct"
    },
    {
      "symbol": "BlockUntil",
      "change": "deprecated; prefer BlockUntilContext"
    }
  ]
}
